      click: () => {
        const board = document.getElementById('board');
        if (!board) return;
        board.toBlob(blob => {
          if (!blob) return morse.toast('Could not save drawing');
          const url = URL.createObjectURL(blob);
          const a = morse.el('a', { href: url, download: 'sketch.png' });
          document.body.appendChild(a);
          a.click();
          a.remove();
          setTimeout(() => URL.revokeObjectURL(url), 1000);
