const bar = "#__next > div:nth-of-type(2) > main > div:nth-of-type(1)";
const grid = "#__next > div:nth-of-type(2) > main > div:nth-of-type(2) > div";

const priceOf = card => {
  const m = (card.textContent || "").match(/\$\s*([\d,]+(?:\.\d+)?)/);
  return m ? parseFloat(m[1].replace(/,/g, "")) : Infinity;
};

function sortByPrice() {
  const g = morse.$(grid);
  if (!g) return;
  const cards = Array.from(g.children);
  cards.sort((a, b) => priceOf(a) - priceOf(b));
  cards.forEach(c => g.appendChild(c));
}

morse.watch(bar, el => {
  if (el.querySelector("[data-morse-sort]")) return;
  el.appendChild(morse.el("button", {
    "data-morse-sort": "",
    type: "button",
    text: "Sort: price low to high",
    style: "margin-left:auto;font:inherit;font-size:14px;color:inherit;background:transparent;border:1px solid currentColor;border-radius:6px;padding:4px 10px;cursor:pointer;opacity:.8",
    on: { click: sortByPrice }
  }));
});

const GRID = "#__next > div:nth-of-type(2) > main > div:nth-of-type(2)";
const HEAD = "#__next > div:nth-of-type(2) > main > div:nth-of-type(1)";

const priceOf = el => {
  const m = el.textContent.match(/\$\s*([\d,]+(?:\.\d+)?)/);
  return m ? parseFloat(m[1].replace(/,/g, "")) : Infinity;
};

morse.watch(HEAD, head => {
  if (head.querySelector("[data-morse-sort]")) return;
  const btn = morse.el("button", {
    text: "Sort by price: low to high",
    "data-morse-sort": "",
    style: "margin-left:auto;font:inherit;font-size:13px;padding:4px 10px;border:1px solid currentColor;border-radius:6px;background:transparent;color:inherit;cursor:pointer",
    on: {
      click: () => {
        const grid = morse.$(GRID);
        if (!grid) return;
        Array.from(grid.children)
          .sort((a, b) => priceOf(a) - priceOf(b))
          .forEach(card => grid.appendChild(card));
      }
    }
  });
  head.appendChild(btn);
});

